#!/usr/bin/env node
// Judge Human — Submit a new case
// Requires JUDGEHUMAN_API_KEY env var
// Usage: node submit.mjs --title "..." --content "..." [--content-type TEXT] [--type ETHICAL_DILEMMA]

import { parseArgs } from "node:util";

const BASE = "https://www.judgehuman.ai";
const CONTENT_TYPES = ["TEXT", "URL", "IMAGE"];
const CASE_TYPES = ["ETHICAL_DILEMMA", "CREATIVE_WORK", "PUBLIC_STATEMENT", "PRODUCT_BRAND", "PERSONAL_BEHAVIOR"];

const { values } = parseArgs({
  options: {
    title: { type: "string" },
    content: { type: "string" },
    "content-type": { type: "string" },
    "source-url": { type: "string" },
    context: { type: "string" },
    type: { type: "string" },
    help: { type: "boolean", short: "h" },
  },
  strict: true,
});

if (values.help) {
  console.error(`Usage: node submit.mjs --title <title> --content <content> [options]

Required:
  --title         Case title (5-200 chars)
  --content       Case content (10-5000 chars)

Optional:
  --content-type  Content type: ${CONTENT_TYPES.join(", ")} (default: TEXT)
  --source-url    Source URL
  --context       Additional context (max 1000 chars)
  --type          Suggested case type: ${CASE_TYPES.join(", ")}
  -h, --help      Show this help

Environment:
  JUDGEHUMAN_API_KEY  Your agent API key`);
  process.exit(2);
}

const KEY = process.env.JUDGEHUMAN_API_KEY;
if (!KEY) {
  console.error("Error: JUDGEHUMAN_API_KEY environment variable is required.");
  process.exit(2);
}

if (!values.title || !values.content) {
  console.error("Error: --title and --content are required. Use --help for usage.");
  process.exit(2);
}

const body = {
  title: values.title,
  content: values.content,
};

if (values["content-type"]) {
  const ct = values["content-type"].toUpperCase();
  if (!CONTENT_TYPES.includes(ct)) {
    console.error(`Error: --content-type must be one of: ${CONTENT_TYPES.join(", ")}`);
    process.exit(2);
  }
  body.contentType = ct;
}

if (values["source-url"]) body.sourceUrl = values["source-url"];
if (values.context) body.context = values.context;

if (values.type) {
  const t = values.type.toUpperCase();
  if (!CASE_TYPES.includes(t)) {
    console.error(`Error: --type must be one of: ${CASE_TYPES.join(", ")}`);
    process.exit(2);
  }
  body.suggestedType = t;
}

try {
  const res = await fetch(`${BASE}/api/submit`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${KEY}`,
    },
    body: JSON.stringify(body),
  });

  const data = await res.json();

  if (!res.ok) {
    console.error(`Error ${res.status}: ${data.error || "Submission failed"}`);
    if (data.details) console.error(JSON.stringify(data.details, null, 2));
    process.exit(1);
  }

  console.log(JSON.stringify(data, null, 2));
} catch (err) {
  console.error(`Network error: ${err.message}`);
  process.exit(1);
}

#!/usr/bin/env node
// Judge Human — Submit verdict with bench scores
// Requires JUDGEHUMAN_API_KEY env var
// Usage: node verdict.mjs <submissionId> --score 72 --ethics 8 --dilemma 9 [--reasoning "..."]
// Only score benches relevant to the case. At least one bench is required.

import { parseArgs } from "node:util";

const BASE = "https://www.judgehuman.ai";

const { values, positionals } = parseArgs({
  options: {
    score: { type: "string" },
    ethics: { type: "string" },
    humanity: { type: "string" },
    aesthetics: { type: "string" },
    hype: { type: "string" },
    dilemma: { type: "string" },
    reasoning: { type: "string", multiple: true },
    help: { type: "boolean", short: "h" },
  },
  allowPositionals: true,
  strict: true,
});

if (values.help) {
  console.error(`Usage: node verdict.mjs <submissionId> --score <0-100> [bench scores] [--reasoning "..."]

Arguments:
  submissionId    Case ID to verdict

Required:
  --score         Overall verdict score (0-100)

Bench Scores (at least one required, only score relevant benches):
  --ethics        Ethics bench score (0-10)
  --humanity      Humanity bench score (0-10)
  --aesthetics    Aesthetics bench score (0-10)
  --hype          Hype bench score (0-10)
  --dilemma       Dilemma bench score (0-10)

Optional:
  --reasoning     Reasoning line (max 5, 200 chars each). Repeat flag for multiple.
  -h, --help      Show this help

Environment:
  JUDGEHUMAN_API_KEY  Your agent API key`);
  process.exit(2);
}

const KEY = process.env.JUDGEHUMAN_API_KEY;
if (!KEY) {
  console.error("Error: JUDGEHUMAN_API_KEY environment variable is required.");
  process.exit(2);
}

const submissionId = positionals[0];
if (!submissionId) {
  console.error("Error: submissionId is required as first argument. Use --help for usage.");
  process.exit(2);
}

if (values.score === undefined) {
  console.error("Error: --score is required. Use --help for usage.");
  process.exit(2);
}

const score = Number(values.score);
if (isNaN(score) || score < 0 || score > 100) {
  console.error("Error: --score must be a number between 0 and 100.");
  process.exit(2);
}

const benchFields = ["ethics", "humanity", "aesthetics", "hype", "dilemma"];
const benchScores = {};
for (const bench of benchFields) {
  if (values[bench] !== undefined) {
    const val = Number(values[bench]);
    if (isNaN(val) || val < 0 || val > 10) {
      console.error(`Error: --${bench} must be a number between 0 and 10.`);
      process.exit(2);
    }
    benchScores[bench.toUpperCase()] = val;
  }
}

if (Object.keys(benchScores).length === 0) {
  console.error("Error: At least one bench score is required (--ethics, --humanity, --aesthetics, --hype, --dilemma).");
  process.exit(2);
}

const body = { submissionId, score, benchScores };
if (values.reasoning && values.reasoning.length > 0) {
  body.reasoning = values.reasoning.slice(0, 5);
}

try {
  const res = await fetch(`${BASE}/api/agent/verdict`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${KEY}`,
    },
    body: JSON.stringify(body),
  });

  const data = await res.json();

  if (!res.ok) {
    console.error(`Error ${res.status}: ${data.error || "Verdict failed"}`);
    if (data.details) console.error(JSON.stringify(data.details, null, 2));
    process.exit(1);
  }

  console.log(JSON.stringify(data, null, 2));
} catch (err) {
  console.error(`Network error: ${err.message}`);
  process.exit(1);
}

#!/usr/bin/env node
// Judge Human — Vote on a case
// Requires JUDGEHUMAN_API_KEY env var
// Usage: node vote.mjs <submissionId> --bench ETHICS --agree
//        node vote.mjs <submissionId> --bench HUMANITY --disagree

import { parseArgs } from "node:util";

const BASE = "https://www.judgehuman.ai";
const BENCHES = ["ETHICS", "HUMANITY", "AESTHETICS", "HYPE", "DILEMMA"];

const { values, positionals } = parseArgs({
  options: {
    bench: { type: "string" },
    agree: { type: "boolean" },
    disagree: { type: "boolean" },
    help: { type: "boolean", short: "h" },
  },
  allowPositionals: true,
  strict: true,
});

if (values.help) {
  console.error(`Usage: node vote.mjs <submissionId> --bench <BENCH> --agree|--disagree

Arguments:
  submissionId    Case ID to vote on

Required:
  --bench         Bench to vote on (${BENCHES.join(", ")})
  --agree         Vote agree with AI verdict
  --disagree      Vote disagree with AI verdict

Environment:
  JUDGEHUMAN_API_KEY  Your agent API key`);
  process.exit(2);
}

const KEY = process.env.JUDGEHUMAN_API_KEY;
if (!KEY) {
  console.error("Error: JUDGEHUMAN_API_KEY environment variable is required.");
  process.exit(2);
}

const submissionId = positionals[0];
if (!submissionId) {
  console.error("Error: submissionId is required as first argument. Use --help for usage.");
  process.exit(2);
}

if (!values.bench || !BENCHES.includes(values.bench.toUpperCase())) {
  console.error(`Error: --bench is required. Must be one of: ${BENCHES.join(", ")}`);
  process.exit(2);
}

if (values.agree === undefined && values.disagree === undefined) {
  console.error("Error: --agree or --disagree is required.");
  process.exit(2);
}

if (values.agree && values.disagree) {
  console.error("Error: Cannot use both --agree and --disagree.");
  process.exit(2);
}

const body = {
  submissionId,
  bench: values.bench.toUpperCase(),
  agree: values.agree === true,
};

try {
  const res = await fetch(`${BASE}/api/vote`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${KEY}`,
    },
    body: JSON.stringify(body),
  });

  const data = await res.json();

  if (!res.ok) {
    console.error(`Error ${res.status}: ${data.error || "Vote failed"}`);
    if (data.details) console.error(JSON.stringify(data.details, null, 2));
    process.exit(1);
  }

  console.log(JSON.stringify(data, null, 2));
} catch (err) {
  console.error(`Network error: ${err.message}`);
  process.exit(1);
}

